actions.command:
rm -rf /tmp/zkflags && mkdir /tmp/zkflags && cd /tmp/zkflags
run(){ echo "### $*"; /workspace/executable "$@" >out 2>err; st=$?; echo status=$st; echo '--out'; sed -n '1,20p' out; echo '--err'; sed -n '1,60p' err; }
for args in '-h' 'help' 'version' '-v' '--version' 'list -h' 'list --help' 'list -W /tmp' 'list --working-dir /tmp' 'list --notebook-dir /tmp' 'list --no-input' 'list -W' 'list --notebook-dir' 'new -h' 'tag -h' 'tag list -h' 'tag -h list' 'tag list --help --bad'; do eval "run $args"; done

cd /tmp/zkflags
run(){ echo "### $*"; /workspace/executable "$@" >out 2>err; st=$?; echo status=$st; echo out=$(cat out | head -c 80 | sed 's/$//'); echo err=$(cat err | head -c 160); }
for args in 'list --version' '--version list' 'list -f json' 'list --format=json' 'list -0' 'list -0x' 'list -abc' 'index -v' 'index --verbose' 'index --force --quiet' 'index --force=x' 'new --title' 'new --extra a=b,c=d' 'new --id abc -p' 'new --date bad -n' 'graph --format json' 'graph --format=json' 'graph -f' 'tag list -f json' 'tag list -s name-' 'tag list -q'; do eval "run $args"; done

